module top_module(
	input [7:0] number,
    output reg [3:0] ones,
    output reg [3:0] tens,
    output reg [3:0] hundreds
    );reg [19:0] shift;
    integer i; 

    always @(number)
    begin
        shift[19:8] = 0;
        shift [7:0] = number;
        for(i=0; i<8; i=i+1)
        begin
            if (shift[11:8] >= 5)
                shift[11:8] = shift[11:8] + 3;
            if (shift[15:12] >= 5)
                shift[15:12] = shift[15:12] + 3;
            if (shift[19:16] >=5)
                shift[19:16] = shift[19:16] + 3;
            shift = shift << 1;
        end
     hundreds = shift[19:16];
     tens = shift[15:12];
     ones = shift[11:8];
     end

endmodule

