    if (a > b) begin
        stage1_max = a;
        stage1_equal_flag = 0;
    end else if (a < b) begin
        stage1_max = b;
        stage1_equal_flag = 0;
    end else begin
        stage1_max = a;
        stage1_equal_flag = 1;
    end
end

