module top_module(input wire fclk,input wire zpos,input wire zneg,input wire int_start,input wire iorq_n,input wire m1_n,input wire wait_n,output reg int_n);wire intend; 
  reg [9:0] intctr; 
  reg [1:0] wr; 
 `ifdef SIMULATE 
  initial 
  begin 
  intctr = 10'b1100000000; 
  end 
 `endif 
  always @(posedge fclk) 
  wr[1:0] <= { wr[0], wait_n }; 
  always @(posedge fclk) 
  begin 
  if( int_start ) 
  intctr <= 10'd0; 
  else if( !intctr[9:8] && wr[1] ) 
  intctr <= intctr + 10'd1; 
  end 
  assign intend = intctr[9:8] || ( (!iorq_n) && (!m1_n) && zneg ); 
  always @(posedge fclk) 
  begin 
  if( int_start ) 
  int_n <= 1'b0; 
  else if( intend ) 
  int_n <= 1'bZ; 
  end 
 endmodule

