module top_module_tb;

    // Testbench signals (sequential circuit)
    reg fclk;
    reg int_start;
    reg iorq_n;
    reg m1_n;
    reg wait_n;
    reg zneg;
    reg zpos;
    wire int_n;

    // Test tracking
    integer test_num;
    integer pass_count;
    integer fail_count;

    // Instantiate the DUT (Device Under Test)
    top_module dut (
        .fclk(fclk),
        .int_start(int_start),
        .iorq_n(iorq_n),
        .m1_n(m1_n),
        .wait_n(wait_n),
        .zneg(zneg),
        .zpos(zpos),
        .int_n(int_n)
    );

    // Clock generation (10ns period)
    initial begin
        fclk = 0;
        forever #5 fclk = ~fclk;
    end

        task reset_dut;

    begin
        int_start = 0;
        iorq_n = 1;
        m1_n = 1;
        wait_n = 1;
        zneg = 0;
        zpos = 0;
        repeat(2) @(posedge fclk);
        #1;
    end
        endtask
    task testcase001;

    begin
        test_num = 1;
        reset_dut();
        int_start = 1;
        @(posedge fclk);
        #1;
        int_start = 0;
        @(posedge fclk);
        #1;

        #1;


        check_outputs(1'b0);
    end
        endtask

    task testcase002;

    begin
        test_num = 2;
        reset_dut();

        int_start = 1;
        @(posedge fclk);
        #1;
        int_start = 0;


        iorq_n = 0;
        m1_n = 0;
        zneg = 1;
        @(posedge fclk);
        #1;

        #1;


        check_outputs(1'b1);
    end
        endtask

    task testcase003;

    begin
        test_num = 3;
        reset_dut();
        int_start = 1;
        @(posedge fclk);
        #1;
        int_start = 0;

